'use strict';
// ── Fyers daily login from the phone (17 Oct 2026) ───────────────────────────────────────────────────────────────────────
// Fyers access tokens expire every day (~06:00 IST) and the refresh-token API is disabled by SEBI, so the token has to be generated by a
// manual login each morning. This helper lets the APP do the second half of that login, so the owner can do the whole thing from a phone:
//   1. open /api/fyers-login/page?key=APP_TOKEN  ->  tap "Fyers login kholo"  ->  log in on Fyers (PIN / TOTP)
//   2. Fyers redirects to a page whose address contains  auth_code=...   ->  copy that whole address
//   3. paste it into the app page  ->  the server exchanges it for an access token (using FYERS_APP_ID + FYERS_SECRET_ID, which are already
//      Railway variables) and switches the running app to the new token. No secret is typed into any page; the token is never shown or logged.
// The new token is also saved to a small file on the Railway volume so a restart the same day keeps it. Nothing here places an order.

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const REDIRECT_URI = 'https://trade.fyers.in/api-login/redirect-uri/index.html';
const FYERS_BASE = 'https://api-t1.fyers.in/api/v3';

function appIdHash(appId, secret) { return crypto.createHash('sha256').update(`${appId}:${secret}`).digest('hex'); }

// JWT 'exp' claim in ms (signature NOT checked - used only to compare freshness), or null
function tokenExpMs(token) {
    try {
        const parts = String(token || '').split('.');
        if (parts.length < 2) return null;
        const json = JSON.parse(Buffer.from(parts[1].replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'));
        const e = Number(json.exp);
        return Number.isFinite(e) && e > 0 ? e * 1000 : null;
    } catch (e) { return null; }
}

// accepts the whole redirected address, "auth_code=...", or the bare code; returns the code or null
function extractAuthCode(input) {
    let s = String(input == null ? '' : input).trim();
    if (!s) return null;
    const m = s.match(/[?&#]auth_code=([^&#\s]+)/i) || s.match(/^auth_code=([^&#\s]+)/i);
    if (m) { try { s = decodeURIComponent(m[1]); } catch (e) { s = m[1]; } }
    s = s.replace(/^["'\s]+|["'\s]+$/g, '');
    return /^[A-Za-z0-9._\-]{20,4000}$/.test(s) ? s : null;     // a bare code is a long JWT-like string
}

function istText(ms) {
    return new Date(ms + 330 * 60000).toISOString().replace('T', ' ').slice(0, 16) + ' IST';
}

// deps are injectable for tests. env: () => process.env-like. post(url, body) -> {data}. apply(token) switches the running app. current() reads it.
function createFyersLogin({ env = () => process.env, post, apply, current, dir, now = Date.now, log = () => {}, fsImpl = fs }) {
    const dataDir = () => dir || env().DATA_DIR || '/data';
    const file = () => path.join(dataDir(), 'fyers-token.json');

    function loginUrl() {
        const appId = String(env().FYERS_APP_ID || '').trim();
        if (!appId) return null;
        return `${FYERS_BASE}/generate-authcode?client_id=${encodeURIComponent(appId)}&redirect_uri=${encodeURIComponent(REDIRECT_URI)}&response_type=code&state=vardaannifty`;
    }

    function status() {
        const tok = current();
        const exp = tokenExpMs(tok);
        return {
            hasToken: !!tok,
            expiresAt: exp ? istText(exp) : null,
            valid: exp ? exp > now() : null,           // null = unreadable token
            minutesLeft: exp ? Math.round((exp - now()) / 60000) : null,
            configured: !!(String(env().FYERS_APP_ID || '').trim() && String(env().FYERS_SECRET_ID || '').trim()),
        };
    }

    function save(token) {
        try {
            fsImpl.mkdirSync(dataDir(), { recursive: true });
            fsImpl.writeFileSync(file(), JSON.stringify({ access_token: token, exp: tokenExpMs(token), savedAt: now() }), { mode: 0o600 });
            return true;
        } catch (e) { log(`[FyersLogin] could not save token file: ${e.message}`); return false; }
    }

    // at boot: use the saved token only if it is valid AND later-expiring than the one already in the environment
    function loadSaved() {
        try {
            const j = JSON.parse(fsImpl.readFileSync(file(), 'utf8'));
            const tok = String(j.access_token || '').trim();
            const exp = tokenExpMs(tok);
            if (!tok || !exp || exp <= now()) return false;
            const curExp = tokenExpMs(current());
            if (curExp && curExp >= exp) return false;
            apply(tok);
            log(`[FyersLogin] saved token loaded (valid till ${istText(exp)})`);
            return true;
        } catch (e) { return false; }
    }

    async function exchange(input) {
        const appId = String(env().FYERS_APP_ID || '').trim(), secret = String(env().FYERS_SECRET_ID || '').trim();
        if (!appId || !secret) return { ok: false, error: 'FYERS_APP_ID ya FYERS_SECRET_ID Railway mein set nahi hai.' };
        const code = extractAuthCode(input);
        if (!code) return { ok: false, error: 'auth_code nahi mila. Fyers login ke baad jo poora address (URL) khula, wahi paste karo.' };
        let res;
        try { res = await post(`${FYERS_BASE}/validate-authcode`, { grant_type: 'authorization_code', appIdHash: appIdHash(appId, secret), code }); }
        catch (e) {
            const d = e && e.response && e.response.data;
            return { ok: false, error: `Fyers ne mana kiya: ${(d && (d.message || d.msg)) || e.message}. Login dobara karke naya address paste karo (code sirf kuch minute chalta hai).` };
        }
        const d = (res && res.data) || {};
        const tok = String(d.access_token || '').trim();
        if (d.s !== 'ok' || !tok) return { ok: false, error: `Fyers ne token nahi diya: ${d.message || d.msg || 'unknown'}. Login dobara karo.` };
        apply(tok);
        const saved = save(tok);
        log(`[FyersLogin] new Fyers access token applied (valid till ${istText(tokenExpMs(tok) || now())}); saved=${saved}`);
        return { ok: true, saved, ...status() };
    }

    return { loginUrl, status, exchange, loadSaved };
}

// phone-friendly page. It reads the key from its own address (?key=...) and never contains the APP_TOKEN or any Fyers secret.
function renderPage() {
    return `<!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Fyers Login</title><style>
:root{--bg:#0f1115;--card:#181b22;--fg:#e8eaed;--mut:#9aa0aa;--ok:#35c27a;--bad:#ff6b6b;--acc:#4c8dff}
@media(prefers-color-scheme:light){:root{--bg:#f4f5f7;--card:#fff;--fg:#14171c;--mut:#5a6270}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.5 system-ui,sans-serif;padding:16px}
.w{max-width:520px;margin:0 auto}h1{font-size:20px;margin:8px 0 12px}.c{background:var(--card);border-radius:12px;padding:14px;margin:12px 0}
.s{color:var(--mut);font-size:14px}a.b,button{display:block;width:100%;text-align:center;background:var(--acc);color:#fff;border:0;border-radius:10px;padding:14px;font-size:16px;text-decoration:none;margin-top:10px}
textarea{width:100%;min-height:110px;border-radius:10px;border:1px solid var(--mut);background:transparent;color:var(--fg);padding:10px;font-size:14px}
.ok{color:var(--ok)}.bad{color:var(--bad)}</style></head><body><div class="w"><h1>🔑 Fyers token (mobile)</h1>
<div class="c"><div id="st" class="s">status check ho raha hai...</div></div>
<div class="c"><b>Step 1</b><div class="s">Fyers par login karo (PIN / TOTP).</div><a class="b" id="go" href="#" target="_blank" rel="noopener">Fyers login kholo</a></div>
<div class="c"><b>Step 2</b><div class="s">Login ke baad jo page khule, uska <u>poora address</u> (URL, jisme <code>auth_code=</code> ho) copy karke yahan paste karo.</div>
<textarea id="in" placeholder="https://trade.fyers.in/api-login/redirect-uri/index.html?...auth_code=..."></textarea>
<button id="mk">Token banao</button><div id="out" class="s" style="margin-top:10px"></div></div></div>
<script>
const key=new URLSearchParams(location.search).get('key')||'';
const H={'Content-Type':'application/json','X-App-Token':key};
function show(s){const e=document.getElementById('st');
 if(!s.configured){e.innerHTML='<span class="bad">FYERS_APP_ID / FYERS_SECRET_ID Railway mein set nahi hain.</span>';return}
 if(!s.hasToken){e.innerHTML='<span class="bad">Token nahi hai. Neeche se banao.</span>';return}
 if(s.valid===null){e.textContent='Token hai (expiry padh nahi paaye).';return}
 e.innerHTML=s.valid?'<span class="ok">Token valid</span> - '+s.expiresAt+' tak ('+s.minutesLeft+' min baaki)':'<span class="bad">Token expire ho chuka</span> ('+s.expiresAt+'). Naya banao.'}
fetch('/api/fyers-login/status',{headers:H}).then(r=>r.json()).then(j=>{show(j.status);const g=document.getElementById('go');
 if(j.loginUrl)g.href=j.loginUrl;else{g.style.display='none'}}).catch(()=>{document.getElementById('st').textContent='status nahi mila (key galat ho sakti hai).'});
document.getElementById('mk').onclick=async()=>{const o=document.getElementById('out');o.textContent='ho raha hai...';
 try{const r=await fetch('/api/fyers-login/exchange',{method:'POST',headers:H,body:JSON.stringify({input:document.getElementById('in').value})});
  const j=await r.json();if(j.ok){o.innerHTML='<span class="ok">Ho gaya. Naya token laga diya.</span>';show(j);document.getElementById('in').value=''}
  else o.innerHTML='<span class="bad">'+String(j.error||j.msg||'error').replace(/[<>&]/g,'')+'</span>'}catch(e){o.textContent='network error'}};
</script></body></html>`;
}

module.exports = { REDIRECT_URI, appIdHash, tokenExpMs, extractAuthCode, createFyersLogin, renderPage };